contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 _digest, bytes32 _r, bytes32 _s) public {
        bool initiallyApproved = c.approvedToLog(msg.sender); if (__ESBMC_reverted()) return;

        bool reverted;
        bool ret;
        bool r = c.logGotRedemptionSignature(_digest, _r, _s); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            ret = r;
        }

        bool approvedAfter = c.approvedToLog(msg.sender); if (__ESBMC_reverted()) return;

        assert(!reverted && ret == initiallyApproved && approvedAfter == initiallyApproved);
    }

    receive() external payable {}
}

