pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(bytes32 _digest, bytes32 _r, bytes32 _s) internal {
        bool initiallyApproved;
        try c.approvedToLog(msg.sender) returns (bool __r) { initiallyApproved = __r; } catch { return; }
        bool reverted;
        bool ret;
        try c.logGotRedemptionSignature(_digest, _r, _s) returns (bool r) {
            ret = r;
        } catch {
            reverted = true;
        }
        bool approvedAfter;
        try c.approvedToLog(msg.sender) returns (bool __r) { approvedAfter = __r; } catch { return; }
        assertTrue(!reverted && ret == initiallyApproved && approvedAfter == initiallyApproved);
    }

    function testFuzz_run(bytes32 _digest, bytes32 _r, bytes32 _s) public {
        _run(_digest, _r, _s);
    }

    receive() external payable {}
}
